import{_ as r,a0 as l,w as a,s as p,ao as s,I as o,x as n,a1 as i,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"你為什麼使用 Linux 和開源軟件？ | LCTT x X-CMD","titleTemplate":false,"description":"你為什麼使用 Linux 和開源軟件？ | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你為什麼使用 Linux 和開源軟件？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你為什麼使用 Linux 和開源軟件？ | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170317 Why do you use Linux and open source software","title":"你為什麼使用 Linux 和開源軟件？","tag":"201706","desc":""},"relativePath":"201706/20170317 Why do you use Linux and open source software.md","filePath":"[post].md"}'),m={name:"201706/20170317 Why do you use Linux and open source software.md"};function d(x,e,L,f,T,g){const t=l("Link");return a(),p("div",null,[e[21]||(e[21]=s('<h1 id="你為什麼使用-linux-和開源軟件" tabindex="-1">你為什麼使用 Linux 和開源軟件？ <a class="header-anchor" href="#你為什麼使用-linux-和開源軟件" aria-label="Permalink to “你為什麼使用 Linux 和開源軟件？”">​</a></h1><blockquote><p>LinuxQuestions.org 的用户分享了他們使用 Linux 和開源技術的原因。我們的用户如何回答這個問題？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BUS_consensuscollab2.png?itok=j5vPMv-V" alt="Why do you use Linux and open source software?" title="Why do you use Linux and open source software?"></p><blockquote><p>圖片來源：opensource.com</p></blockquote><p>在網站問答區發佈時我曾經提到過，儘管我一般會回答來自用户問題，但偶爾我也會反過來問讀者一些問題。我並沒有在問答區第一期文章這樣做，看起來有點姍姍來遲。我最近在 LinuxQuestions.org 上提問了兩個相關的問題，收到了很多回復。讓我們看看我們的用户對同樣的問題和 LinuxQuestions.org 的回答的對比。</p><h3 id="你為什麼使用-linux" tabindex="-1">你為什麼使用 Linux？ <a class="header-anchor" href="#你為什麼使用-linux" aria-label="Permalink to “你為什麼使用 Linux？”">​</a></h3>',6)),o("p",null,[e[1]||(e[1]=n("我向 LinuxQuestions.org 社區提問的第一個問題是：",-1)),o("strong",null,[i(t,{href:"http://www.linuxquestions.org/questions/linux-general-1/what-are-the-reasons-you-use-linux-4175600842/"},{default:u(()=>[...e[0]||(e[0]=[n("你們使用 Linux 的原因是什麼？",-1)])]),_:1})])]),e[22]||(e[22]=s('<h4 id="回答集錦" tabindex="-1">回答集錦 <a class="header-anchor" href="#回答集錦" aria-label="Permalink to “回答集錦”">​</a></h4><p><em>oldwierdal</em>：我用 Linux 是因為它運行快速、安全、可靠。在全世界的貢獻者的參與下，Linux 或許已經成為當前我們能用到的最先進和最具創新的軟件。Linux 的用户體驗就像紅絲絨蛋糕上的糖衣一樣令人回味無窮；此外，Linux 是免費的。</p><p><em>Timothy Miller</em>：我最開始使用 Linux 是因為它免費的，而且那時候我的經濟條件無法承受購買新的 Windows 系統正版授權的費用。</p><p><em>ondoho</em> ：因為它是一個擁有全球性社區為之努力、獨立的草根操作系統。因為它在各方面都是自由的。因為它有足夠多的理由讓我們信任它。</p><p><em>joham34</em>：穩定、免費、安全，能夠運行在低配置的電腦上，提供良好技術支持的社區，感染病毒的幾率更小。</p><p><em>Ook</em>：我用 Linux 是因為它可以完成工作，對我來説 Windows 系統在某些事上從來都不能做好。我不得不浪費時間和金錢讓 Windows 繼續正常運行下去。</p><p><em>rhamel</em>：我非常擔心個人隱私泄露在網上。我意識到我不得不在隱私和便利性之間做出妥協。我可能是在騙自己但我確實認為 Linux 至少在某種程度上給了我一定的隱私權。</p><p><em>educateme</em>：我使用 Linux 因為它的開放、好學、熱情樂於助人的社區。而且，它是免費的。</p><p><em>colinetsegers</em>：我為什麼用 Linux？原因不止一個。簡單的説有以下幾點：</p><ol><li>自由分享知識的理念。</li><li>瀏覽網頁的時候有安全感。</li><li>大量免費、有用的軟件。</li></ol><p><em>bamunds</em>：因為我熱愛自由。</p><p><em>cecilskinner1989</em>：我用 Linux 的兩個原因：穩定性和隱私。</p><h3 id="你為什麼使用開源軟件" tabindex="-1">你為什麼使用開源軟件？ <a class="header-anchor" href="#你為什麼使用開源軟件" aria-label="Permalink to “你為什麼使用開源軟件？”">​</a></h3>',13)),o("p",null,[e[3]||(e[3]=n("第二個問題相對更加寬泛：",-1)),o("strong",null,[i(t,{href:"http://www.linuxquestions.org/questions/linux-general-1/what-are-the-reasons-you-use-open-source-software-4175600843/"},{default:u(()=>[...e[2]||(e[2]=[n("你為什麼使用開源軟件？",-1)])]),_:1})]),e[4]||(e[4]=n("你會注意到儘管有些回覆是有重複的部分，但用户的回答大體上的語氣是不同的，有些用户的回答得到很多人的贊同和支持，也有不少用户的回答不怎麼被其他人認同。",-1))]),e[23]||(e[23]=s('<h4 id="回答集錦-1" tabindex="-1">回答集錦 <a class="header-anchor" href="#回答集錦-1" aria-label="Permalink to “回答集錦”">​</a></h4><p><em>robert leleu</em>：温馨、合作的氛圍是我沉溺於開源的主要原因。</p><p><em>cjturner</em>：對於應用而言，開源正好反映了帕累托法則；不做二次開發的話，一個軟件包最終可能只能滿足你的 80% 的需求，而你需要自己解決剩下的 20%。開源給了你一個途徑，通過社區來解決這種問題，你可以自己努力實現（如果你有相關的技能）或者花錢有償請人實現你的需求。</p><p><em>Timothy Miller</em>：我喜歡這種體驗，我能夠自己檢查源代碼來確定我所選擇的軟件是安全的。</p><p><em>teckk</em>：沒有繁瑣的許可要求或者數字版權管理（DRM），而且每個人都可以獲得它。</p><p><em>rokytnji</em> ：像零花錢，摩托車部件，孫輩的生日禮物那樣令人愉悦。</p><p><em>timl</em>：沒有自由軟件避免隱私的泄露是不可能。</p><p><em>hazel</em>：我喜歡自由軟件的哲學，但如果 Linux 是一個糟糕的操作系統我也會理性的不去使用它。我使用 Linux 是因為我熱愛 Linux，而且你也能免費獲得它就像免費的啤酒一樣。事實上它也如言論自由一般自由不受拘束，使用開源軟件讓我感覺很舒服。但是如果我發現我的計算機有一個硬件需要專有固件的配合才能發揮功能，我也會使用專有固件。</p><p><em>lm8</em>：我使用開源軟件是因為我不必擔心由於開發公司的破產或者決定停止維護它而導致它可能會變得過時或者被廢棄。我能夠自己來完成後續的更新、維護。如果我想讓軟件能夠做我想的任何事情，我也可以進一步定製它，但是如果有更多的特性，那就更好了。我也喜歡開源，因為開源我才能夠和朋友、同事們分享我喜歡的程序。</p><p><em>donguitar</em>：因為它能夠讓我學到很多，也讓我讓別人學到了很多。</p><h3 id="該你回答了" tabindex="-1">該你回答了 <a class="header-anchor" href="#該你回答了" aria-label="Permalink to “該你回答了”">​</a></h3><p>所以，<em><strong>你</strong></em> 使用 Linux 的原因是什麼？ <em><strong>你</strong></em> 使用開源軟件的原因是什麼？請在評論區告訴我們。</p><h4 id="最後的補充" tabindex="-1">最後的補充 <a class="header-anchor" href="#最後的補充" aria-label="Permalink to “最後的補充”">​</a></h4>',13)),o("p",null,[e[6]||(e[6]=n("最後，在以後的文章裏你想看到什麼問題的回答？是社區的建立和維護的相關問題，還是你想知道如何對一個開源項目作出貢獻，還是更有技術性的問題 — ",-1)),i(t,{href:"https://opensource.com/thequeue-submit-question"},{default:u(()=>[...e[5]||(e[5]=[n("向我們提交你對 Linux 和 開源的問題",-1)])]),_:1}),e[7]||(e[7]=n("。",-1))]),e[24]||(e[24]=o("hr",null,null,-1)),e[25]||(e[25]=o("p",null,"作者簡介：",-1)),e[26]||(e[26]=o("p",null,"Jeremy Garcia - Jeremy Garcia 是 LinuxQuestions.org 的創立者同時也是一位熱情中不乏現實主義的開源倡導者。你可以在 Twitter 上關注 Jeremy：@linuxquestions",-1)),e[27]||(e[27]=o("hr",null,null,-1)),o("p",null,[e[9]||(e[9]=n("via: ",-1)),i(t,{href:"https://opensource.com/article/17/3/why-do-you-use-linux-and-open-source-software"},{default:u(()=>[...e[8]||(e[8]=[n("https://opensource.com/article/17/3/why-do-you-use-linux-and-open-source-software",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=n("作者：",-1)),i(t,{href:"https://opensource.com/users/jeremy-garcia"},{default:u(()=>[...e[10]||(e[10]=[n("Jeremy Garcia",-1)])]),_:1}),e[14]||(e[14]=n(" 譯者：",-1)),i(t,{href:"https://github.com/WangYueScream"},{default:u(()=>[...e[11]||(e[11]=[n("WangYueScream",-1)])]),_:1}),e[15]||(e[15]=n(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:u(()=>[...e[12]||(e[12]=[n("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...e[16]||(e[16]=[n("LCTT",-1)])]),_:1}),e[19]||(e[19]=n(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:u(()=>[...e[17]||(e[17]=[n("Linux中國",-1)])]),_:1}),e[20]||(e[20]=n(" 榮譽推出",-1))])])}const b=r(m,[["render",d]]);export{w as __pageData,b as default};
